private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
  int octet = bb.get(i);
  if ((octet & 0x80) == 0) {
    sb.append((char) octet);
    return i + 1;
  } else if ((octet & 0xE0) == 0xC0) {
    if (i + 1 >= bb.limit()) {
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
    int octet2 = bb.get(i + 1);
    if ((octet2 & 0xC0) != 0x80) {
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
    sb.append((char) (((octet & 0x1F) << 6) | (octet2 & 0x3F)));
    return i + 2;
  } else if ((octet & 0xF0) == 0xE0) {
    if (i + 2 >= bb.limit()) {
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
    int octet2 = bb.get(i + 1);
    int octet3 = bb.get(i + 2);
    if ((octet2 & 0xC0) != 0x80 || (octet3 & 0xC0) != 0x80) {
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
    sb.append((char) (((octet & 0x0F) << 12) | ((octet2 & 0x3F) << 6) | (octet3 & 0x3F)));
    return i + 3;
  } else if ((octet & 0xF8) == 0xF0) {
    if (i + 3 >= bb.limit()) {
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
    int octet2 = bb.get(i + 1);
    int octet3 = bb.get(i + 2);
    int octet4 = bb.get(i + 3);
    if ((octet2 & 0xC0) != 0x80 || (octet3 & 0xC0) != 0x80 || (octet4 & 0xC0) != 0x80) {
      throw new IllegalArgumentException("Invalid UTF-8 encoding");
    }
    sb.append((char) (((octet & 0x07) << 18) | ((octet2 & 0x3F) << 12) | ((octet3 & 0x3F) << 6) | (octet4 & 0x3F)));
    return i + 4;
  } else {
    throw new IllegalArgumentException("Invalid UTF-8 encoding");
  }
}

