public void enlarge(final int size) {
    // Step 1: Check if the current capacity is enough to hold the additional bytes
    if (this.data.length < this.length + size) {
        // Step 2: Calculate the new capacity
        int newCapacity = this.data.length + size;
        // Step 3: Create a new array with the new capacity
        byte[] newData = new byte[newCapacity];
        // Step 4: Copy the current data to the new array
        System.arraycopy(this.data, 0, newData, 0, this.length);
        // Step 5: Set the new array as the current data
        this.data = newData;
    }
}

