public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Create a new mapping from graph to graph
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>(graph, graph);

    // Add a mapping from each vertex to itself
    for (V vertex : graph.getVertices()) {
        mapping.addMapping(vertex, vertex);
    }

    // Add a mapping from each edge to itself
    for (E edge : graph.getEdges()) {
        mapping.addMapping(edge, edge);
    }

    return mapping;
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null && files.length > 0) {
            for (File f : files) {
                forceDeleteOnExit(f);
            }
        }
    }
    if (!file.delete()) {
        throw new IOException("Failed to delete file " + file.getAbsolutePath());
    }
}

