public Mappings diffStructure(String tableName, Mappings mappings) {
    // Step 1: Check if the input mappings are null or empty
    if (mappings == null || mappings.isEmpty()) {
        return null;
    }

    // Step 2: Get the current mappings from the index
    Mappings currentMappings = getMappings(tableName);

    // Step 3: Check if the current mappings are null or empty
    if (currentMappings == null || currentMappings.isEmpty()) {
        return null;
    }

    // Step 4: Create a new mappings object to store the diff
    Mappings diffMappings = new Mappings();

    // Step 5: Iterate over the input mappings and compare with the current mappings
    for (Mapping mapping : mappings) {
        if (!currentMappings.contains(mapping)) {
            diffMappings.add(mapping);
        }
    }

    // Step 6: Return the diff mappings
    return diffMappings;
}

