public static long compressTimeBucket(long timeBucket, int dayStep) {
  if (dayStep <= 0) {
    throw new IllegalArgumentException("Day step must be positive");
  }
  if (timeBucket < 0) {
    throw new IllegalArgumentException("Time bucket must be non-negative");
  }
  long days = timeBucket / 1000000;
  long remainder = timeBucket % 1000000;
  long step = days / dayStep;
  long newDays = step * dayStep;
  long newTimeBucket = newDays * 1000000 + remainder;
  return newTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) {
            size += 1;
        } else if (ch <= 0x07FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            size += 4;
            i++;
        } else {
            size += 3;
        }
    }
    return size;
}

