public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        throw new NullPointerException("byteArrayValue cannot be null");
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength out of bounds: " + byteLength);
    }
    if (byteLength == 0) {
        return this;
    }
    int newLength = length + byteLength;
    if (newLength > data.length) {
        grow(newLength);
    }
    System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
    length = newLength;
    return this;
}

