    }
    if (off < 0 || off > b.length) {
        throw new IndexOutOfBoundsException("The offset must be non-negative and less than or equal to the length of the byte array");
    }
    if (len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("The length must be non-negative and less than or equal to the length of the byte array minus the offset");
