protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the edge already exists in the index
    if (this.index.containsKey(sourceVertex) && this.index.get(sourceVertex).contains(targetVertex)) {
        return;
    }

    // Add the edge to the index
    if (!this.index.containsKey(sourceVertex)) {
        this.index.put(sourceVertex, new HashSet<V>());
    }
    this.index.get(sourceVertex).add(targetVertex);

    // Add the edge to the reverse index
    if (!this.reverseIndex.containsKey(targetVertex)) {
        this.reverseIndex.put(targetVertex, new HashSet<V>());
    }
    this.reverseIndex.get(targetVertex).add(sourceVertex);
}

