public final byte[] toByteArray() {
    // Step 1: Check if the buffer is null or empty
    if (buffer == null || buffer.length == 0) {
        return new byte[0];
    }

    // Step 2: Calculate the total length of the buffer
    int totalLength = 0;
    for (ByteBuffer b : buffer) {
        totalLength += b.remaining();
    }

    // Step 3: Create a new byte array with the total length
    byte[] result = new byte[totalLength];

    // Step 4: Copy the contents of each buffer into the result array
    int offset = 0;
    for (ByteBuffer b : buffer) {
        int length = b.remaining();
        b.get(result, offset, length);
        offset += length;
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    sb.append('\r');
                    i++;
                } else if (nextChar == 't') {
                    sb.append('\t');
                    i++;
                } else if (nextChar == 'b') {
                    sb.append('\b');
                    i++;
                } else if (nextChar == 'f') {
                    sb.append('\f');
                    i++;
                } else if (nextChar == '\\') {
                    sb.append('\\');
                    i++;
                } else if (nextChar == '\'') {
                    sb.append('\'');
                    i++;
                } else if (nextChar == '\"') {
                    sb.append('\"');
                    i++;
                } else if (nextChar == '0') {
                    sb.append('\0');
                    i++;
                } else if (nextChar == 'u') {
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 5;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                } else {
                    throw new Exception("Invalid escape sequence");
                }
            } else {
                throw new Exception("Invalid escape sequence");
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

