public final MatchResult match(CharSequence uri) {
    // Step 1: Check if the URI is null or empty
    if (uri == null || uri.length() == 0) {
        return null;
    }

    // Step 2: Check if the URI matches the pattern
    if (!uri.toString().matches(pattern)) {
        return null;
    }

    // Step 3: Extract the matched groups from the URI
    Matcher matcher = pattern.matcher(uri);
    if (!matcher.find()) {
        return null;
    }

    // Step 4: Create a MatchResult object with the matched groups
    MatchResult result = new MatchResult();
    for (int i = 0; i < matcher.groupCount(); i++) {
        result.addGroup(matcher.group(i + 1));
    }

    return result;
}

