private String unescapeId(String input) {
    // Step 1: Check if the input is null or empty
    if (input == null || input.isEmpty()) {
        return input;
    }

    // Step 2: Check if the input starts with a backslash
    if (input.charAt(0) == '\\') {
        // Step 3: Remove the backslash and return the rest of the string
        return input.substring(1);
    }

    // Step 4: Check if the input contains any escaped characters
    if (input.contains("\\")) {
        // Step 5: Replace all escaped characters with their unescaped versions
        return input.replaceAll("\\\\", "");
    }

    // Step 6: Return the input as is
    return input;
}

