public void abbreviate(final int nameStart,final StringBuffer buf){
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart: " + nameStart);
    }
    int nameEnd = buf.length() - 1;
    while (nameEnd > nameStart && Character.isWhitespace(buf.charAt(nameEnd))) {
        nameEnd--;
    }
    if (nameEnd <= nameStart) {
        throw new IllegalArgumentException("Invalid name: " + buf.substring(nameStart));
    }
    buf.setCharAt(nameStart, Character.toUpperCase(buf.charAt(nameStart)));
    for (int i = nameStart + 1; i <= nameEnd; i++) {
        char c = buf.charAt(i);
        if (Character.isWhitespace(c)) {
            buf.setCharAt(i, '_');
        } else {
            buf.setCharAt(i, Character.toLowerCase(c));
        }
    }
}

